package com.lasheel.smartpantry;
import android.app.*;import android.content.*;import android.database.*;import android.os.*;import android.widget.*;
public class MainActivity extends Activity {DB db;public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);}protected void onResume(){super.onResume();draw();}void draw(){LinearLayout l=UI.page(this,"Smart Pantry Manager");UI.button(this,l,"Add ingredient",()->startActivity(new Intent(this,EditActivity.class)));UI.button(this,l,"Suggested recipes",()->startActivity(new Intent(this,SuggestionsActivity.class)));UI.button(this,l,"Settings",()->startActivity(new Intent(this,SettingsActivity.class)));UI.text(this,l,"Your pantry (tap an item to edit):");try(Cursor c=db.pantry()){if(c.getCount()==0)UI.text(this,l,"Pantry empty. Add an ingredient to begin.");while(c.moveToNext()){int id=c.getInt(0);String label=c.getString(1)+" — "+c.getDouble(2)+" "+c.getString(3);UI.button(this,l,label,()->{Intent i=new Intent(this,EditActivity.class);i.putExtra("id",id);startActivity(i);});}}}}